#!/usr/bin/env bash
# R1 (docs/sdd/token-budget-guard): token-budget.json is the single baseline, generated by token-measure.py
# from a release commit that it names; later it may rise only via [token-budget-raise] commits (R9).
# A missing or broken budget fails closed; main passes at 0 increase.
. "$(dirname "$0")/lib.sh"; . "$(dirname "$0")/token-budget-helpers.sh"
W="$(mktemp -d)"; trap 'rm -rf "$W"' EXIT
B="$REPO_ROOT/token-budget.json"
if [ -f "$B" ]; then
  ok "R1: token-budget.json exists"
  CBB="$REPO_ROOT/scripts/check-budget-baseline.sh"
  expect_exit 0 "R1: this repo's budget is its release copy plus only [token-budget-raise] raises" -- bash "$CBB" "$REPO_ROOT"
  # provenance on a throwaway repo: release copy -> approved raise passes; silent / uncommitted raise and an
  # edited release copy fail (docs/sdd/token-budget-guard R1 baseline provenance, R9)
  R="$(tb_repo)"; trap 'rm -rf "$W" "$R"' EXIT
  c="$(git -C "$R" rev-parse HEAD)"
  python3 "$TM" budget --root "$R" --tag v0.0.1 --commit "$c" --out "$R/token-budget.json" --selftest-repo "$R" >/dev/null 2>&1
  git -C "$R" commit -qam "chore(ci): ratchet token budget down to v0.0.1 [automated] [skip ci]"; git -C "$R" tag v0.0.1
  expect_exit 0 "R1: a fresh ratchet copy passes" -- bash "$CBB" "$R"
  budget_headroom "$R" 5; git -C "$R" commit -qam "chore(budget): raise retest-bug [token-budget-raise]"
  expect_exit 0 "R1: an approved [token-budget-raise] commit after the release passes" -- bash "$CBB" "$R"
  budget_headroom "$R" 1; expect_exit 1 "R1: an uncommitted raise fails" -- bash "$CBB" "$R"
  git -C "$R" reset -q --hard v0.0.1; budget_headroom "$R" 5; git -C "$R" commit -qam "chore: tweak budget"
  expect_exit 1 "R1: a raise without [token-budget-raise] fails" -- bash "$CBB" "$R"
  git -C "$R" reset -q --hard v0.0.1; git -C "$R" tag -d v0.0.1 >/dev/null; git -C "$R" reset -q --hard "$c"
  python3 "$TM" budget --root "$R" --tag v0.0.1 --commit "$c" --out "$R/token-budget.json" --selftest-repo "$R" >/dev/null 2>&1
  budget_headroom "$R" 1; git -C "$R" commit -qam "chore(ci): ratchet token budget down to v0.0.1 [automated] [skip ci]"; git -C "$R" tag v0.0.1
  expect_exit 1 "R1: a release copy that differs from its measurement fails" -- bash "$CBB" "$R"
else
  fail "R1: token-budget.json missing"
fi
expect_exit 0 "R1: the current tree passes the budget (0 increase)" -- python3 "$TM" check --root "$REPO_ROOT" --budget "$B" --selftest-repo "$REPO_ROOT"
expect_exit 2 "R1: a missing budget fails closed" -- python3 "$TM" check --root "$REPO_ROOT" --budget "$W/none.json" --selftest-repo "$REPO_ROOT"
echo '{"skills": 3}' > "$W/bad.json"
expect_exit 2 "R1: a malformed budget fails closed" -- python3 "$TM" check --root "$REPO_ROOT" --budget "$W/bad.json" --selftest-repo "$REPO_ROOT"
finish
